import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Pilot setup","description":"","frontmatter":{},"headers":[],"relativePath":"pilot-setup.md","filePath":"pilot-setup.md","lastUpdated":1794096925000}'),i={name:"pilot-setup.md"};function r(o,e,h,d,l,c){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="pilot-setup" tabindex="-1">Pilot setup <a class="header-anchor" href="#pilot-setup" aria-label="Permalink to &quot;Pilot setup&quot;">​</a></h1><p>This page takes a pilot team from an empty host to a running instance with team login and, if your pilot includes it, an active Enterprise licence. It collects the steps in the order that avoids the known traps; the linked pages hold the details.</p><p><strong>Edition:</strong> Community (install, team login, admins) · Enterprise (licence and the features it unlocks) · <strong>Who:</strong> the operator who installs the chart and the first administrator</p><p>Placeholders in capitals, such as <code>YOUR_HOST</code> or <code>YOUR_USERNAME</code>, stand for your own values.</p><h2 id="who-operates-what" tabindex="-1">Who operates what <a class="header-anchor" href="#who-operates-what" aria-label="Permalink to &quot;Who operates what&quot;">​</a></h2><p>Open AgentHub is self-hosted: you run it on your own infrastructure, and we operate nothing for you. We have no remote access to your systems by default, and the software transfers no prompts or files to us automatically. The licence report and your contact with support (email, screen share) carry only metadata or the content you choose to share.</p><table tabindex="0"><thead><tr><th>You run and are responsible for</th><th>Notes</th></tr></thead><tbody><tr><td>Kubernetes, ingress, DNS and TLS certificates</td><td>The quickstart can set up a single-node cluster for you</td></tr><tr><td>Postgres and S3-compatible object storage, and their backups</td><td>See <a href="/docs/upgrading#before-every-upgrade">Before every upgrade</a></td></tr><tr><td>Your identity provider (OIDC)</td><td>See <a href="#_2-team-login-oidc">Team login</a></td></tr><tr><td>Network security, including egress from the instance</td><td></td></tr><tr><td>The agents&#39; provider accounts: your own subscriptions or API keys</td><td>See <a href="/docs/provider-login">Provider login</a></td></tr><tr><td>Upgrades, with <code>helm upgrade --version</code></td><td>See <a href="/docs/upgrading">Upgrading</a></td></tr></tbody></table><p>What we provide is the software, the Enterprise licence and, for Enterprise customers, the support and onboarding described on <a href="/docs/support">Support</a>.</p><h2 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h2><p>Pick one of the two paths on <a href="/docs/getting-started">Install</a>. Both install the current release.</p><table tabindex="0"><thead><tr><th>Path</th><th>When</th><th>Command</th></tr></thead><tbody><tr><td>Quickstart</td><td>One Linux host, or Docker Desktop on macOS or Windows, without an existing cluster</td><td><code>curl -fsSL https://open-agenthub.github.io/install.sh | sh</code> (Windows: <code>install.ps1</code>)</td></tr><tr><td>Helm</td><td>You already run Kubernetes</td><td><code>helm repo add agenthub https://open-agenthub.github.io/open-agenthub</code>, then <code>helm install</code> as shown on <a href="/docs/getting-started#you-have-a-kubernetes-cluster">Install</a></td></tr></tbody></table><p>The quickstart sets up persistent Postgres and object storage for you. With Helm, configure object storage as well (<code>s3.*</code>, or <code>objectStorage.enabled=true</code>): without it, sessions cannot resume in a fresh pod and uploaded files disappear with the pod.</p><p>For a pilot that may run longer than a test, prefer your own Postgres (<code>postgres.enabled=false</code> and <code>externalDatabase.connectionString</code>); the bundled one is meant for evaluation. Keep all settings in one values file from the start, such as <code>my-values.yaml</code>, and pass it to every <code>helm upgrade</code> with <code>-f</code>. That file holds secrets: keep it out of version control.</p><p>The <a href="/docs/evaluate">evaluation checklist</a> lists what to prepare (hostname, TLS certificate, identity provider, Git access, a model account) and how long each step took when we measured it.</p><h2 id="_2-team-login-oidc" tabindex="-1">2. Team login (OIDC) <a class="header-anchor" href="#_2-team-login-oidc" aria-label="Permalink to &quot;2. Team login (OIDC)&quot;">​</a></h2><p>With the chart&#39;s default configuration and no identity provider, the chart generates one API key, and that key acts as an administrator. For a team, switch to OIDC. Do it in this order:</p><ol><li><p><strong>Choose the first administrator.</strong> Under OIDC nobody is an administrator until one is named. Use that person&#39;s sign-in name as your identity provider issues it in the <code>preferred_username</code> claim.</p></li><li><p><strong>Register the client</strong> at your identity provider: a public client with Authorization Code Flow and PKCE, redirect URI <code>https://YOUR_HOST/auth/callback</code>, post-logout redirect <code>https://YOUR_HOST</code>, web origin <code>https://YOUR_HOST</code>, JWT access tokens for your audience, and refresh tokens (<code>offline_access</code>). <a href="/docs/getting-started#_2-sign-in">Install → Sign in</a> lists every requirement.</p></li><li><p><strong>Set the administrator and the OIDC values in the same upgrade</strong>, so there is no moment in which the instance has team login but no administrator:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># my-values.yaml (excerpt)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ingress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_HOST</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  tlsSecretName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">YOUR_TLS_SECRET</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">frontendOrigin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://YOUR_HOST</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">oidc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  authority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://YOUR_ISSUER</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  clientId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agenthub</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  audience</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">agenthub</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ee</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  admins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR_USERNAME&quot;</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub/open-agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-values.yaml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --version</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TARGET_VERSION</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 15m</span></span></code></pre></div><p><code>TARGET_VERSION</code> is the release you run, such as <code>1.22.0</code>; naming it keeps the upgrade from moving to a newer release. The timeout leaves room for the backend&#39;s startup, which may take up to about 10.5 minutes; see <a href="/docs/upgrading#_4-upgrade">Upgrading</a>.</p></li><li><p><strong>Sign in as that administrator first</strong>, before you share the URL. Then promote further administrators under <strong>Settings → Users &amp; seats → Admins &amp; roles</strong>.</p></li></ol><p><code>ee.admins</code> takes comma-separated names. Names listed there cannot be demoted in the app, so they remain a way back in if role settings go wrong. Despite the <code>ee.</code> prefix, the value works in both editions. Groups from your identity provider can grant the admin role only with an Enterprise licence; keep at least one name in <code>ee.admins</code> as a fallback.</p><p>Data created while the API key was in use belongs to the key&#39;s user name and becomes visible to an OIDC user with the same name. Read <a href="/docs/admin#switching-from-the-api-key-to-oidc">Switching from the API key to OIDC</a> before you switch. If your identity provider uses a certificate from an internal certificate authority, see <a href="/docs/getting-started#move-the-quickstart-to-team-login">team login</a> for <code>backend.trustedCaConfigMap</code>.</p><h2 id="_3-enterprise-licence" tabindex="-1">3. Enterprise licence <a class="header-anchor" href="#_3-enterprise-licence" aria-label="Permalink to &quot;3. Enterprise licence&quot;">​</a></h2><p><strong>Enterprise.</strong> The Community edition is fully usable without a licence. A licence unlocks the Enterprise features: sharing, group roles, usage limits, the agent allowlist, Slack and the others marked Enterprise in the <a href="/docs/features">feature overview</a>.</p><p>The licence is a signed token. The instance verifies it offline and stores it in its database. No chart value switches Enterprise features on.</p><h3 id="how-an-instance-gets-a-licence" tabindex="-1">How an instance gets a licence <a class="header-anchor" href="#how-an-instance-gets-a-licence" aria-label="Permalink to &quot;How an instance gets a licence&quot;">​</a></h3><p>An administrator activates the licence under <strong>Settings → License</strong>. Which way applies depends on how you buy.</p><p><strong>If you have an order form, your licence is issued to you; do not use the online checkout, which starts a trial for new billing addresses.</strong></p><table tabindex="0"><thead><tr><th>You buy</th><th>How the token reaches the instance</th></tr></thead><tbody><tr><td><strong>With an order form</strong> (invoice subscription or a licence issued by us)</td><td>Either we hand the token to you: paste it into <strong>License token</strong> and click <strong>Activate</strong>. Or you retrieve it yourself: click <strong>Get enterprise license</strong>, enter only the <strong>Billing email</strong> from your order form, and click <strong>Retrieve license</strong>, not <strong>Continue to checkout</strong>.</td></tr><tr><td><strong>Self-service checkout</strong></td><td><strong>Get enterprise license</strong> asks for billing email, organisation and seats and redirects to the payment provider; the instance then activates the licence itself. It starts a trial for new billing addresses and is not the path for customers with an order form.</td></tr></tbody></table><p>The licence can be active before the first invoice is paid. Only an administrator sees <strong>Settings → License</strong>.</p><div class="warning custom-block"><p class="custom-block-title">DRAFT: payment and term details</p><p>How invoices, payment and the licence term relate is set by your order form. The order form these pages refer to is still a draft and not approved; your signed order form applies.</p></div><h3 id="licence-status" tabindex="-1">Licence status <a class="header-anchor" href="#licence-status" aria-label="Permalink to &quot;Licence status&quot;">​</a></h3><p>After activation the <strong>Enterprise license</strong> card shows:</p><ul><li>a badge: <strong>active</strong>, <strong>invalid</strong> (a token is stored but does not verify or has expired) or <strong>not activated</strong>;</li><li><strong>Plan</strong>, <strong>Organization</strong> and <strong>Seats included</strong>;</li><li><strong>Valid until</strong> for a licence with a fixed end, otherwise <strong>Renewal: automatic</strong>;</li><li><strong>Last successful report</strong>, <strong>Enterprise features stop without renewal</strong> and <strong>Last report error</strong>.</li></ul><h3 id="daily-report-and-renewal" tabindex="-1">Daily report and renewal <a class="header-anchor" href="#daily-report-and-renewal" aria-label="Permalink to &quot;Daily report and renewal&quot;">​</a></h3><p>About 30 seconds after the backend starts, and then once every 24 hours, the instance reports to the licence service. The report contains the licence token, the number of seats in use and a random key that identifies the instance; no user names, prompts or content. The answer is a renewed token. The licence service&#39;s source currently issues tokens valid for 45 days; this was not verified against the deployed service. What counts is the expiry of the token your instance has stored, shown on the card as <strong>Enterprise features stop without renewal</strong>.</p><ul><li><strong>Without a successful report</strong>, the Enterprise features turn off when the stored token expires. Licence expiry turns off Enterprise features, not the Community edition. It does not delete existing data, but access that depends on Enterprise features, such as sharing, can go away. If a licence is revoked, the features can stop before that date.</li><li><strong>The backend needs outbound HTTPS</strong> to the licence service (chart value <code>ee.license.serviceUrl</code>). The chart sets no egress policy for the backend namespace; your own firewall, proxy or network policy must allow it. An empty value disables reporting, and the licence then stops at the token&#39;s date.</li><li><strong>One licence per instance.</strong> Use each licence on one instance; ask support before moving it.</li></ul><h3 id="when-the-licence-warning-shows-or-reporting-fails" tabindex="-1">When the licence warning shows or reporting fails <a class="header-anchor" href="#when-the-licence-warning-shows-or-reporting-fails" aria-label="Permalink to &quot;When the licence warning shows or reporting fails&quot;">​</a></h3><p>By default the card warns seven days before the stop date (<code>ee.license.reportWarningDays</code>): <em>Enterprise features stop at … unless the license renews.</em> Check <strong>Last report error</strong>:</p><table tabindex="0"><thead><tr><th>Last report error</th><th>What it means</th><th>What to do</th></tr></thead><tbody><tr><td><code>License service request failed. Check connectivity and service availability.</code></td><td>The backend could not reach the licence service</td><td>Check DNS, firewall, proxy and egress from the backend pods to the host in <code>ee.license.serviceUrl</code></td></tr><tr><td><code>License service rejected the report (HTTP 403).</code></td><td>Can mean, among other things, that the licence is no longer active; the instance does not keep the service&#39;s reason</td><td>Contact support with the error and the stop date; support checks the cause</td></tr><tr><td><code>License service rejected the report (HTTP 409).</code></td><td>The licence service refused the report for this instance</td><td>Contact support with the error and the stop date</td></tr><tr><td><code>License service rejected the report (HTTP 401).</code></td><td>Can mean, among other things, that the token has expired; the instance does not keep the service&#39;s reason</td><td>Contact support with the error and the stop date; support checks the cause</td></tr><tr><td><code>License token has no license id. Re-activate it to enable reporting.</code></td><td>An old token without metering</td><td>Activate the token again, or ask support for a current one</td></tr></tbody></table><p>Then:</p><ol><li>Note the date under <strong>Enterprise features stop without renewal</strong>: that is how much time is left.</li><li>After fixing connectivity, restart the backend to report at once instead of at the next scheduled time: <code>kubectl -n agenthub rollout restart deployment/agenthub-backend</code>. About 30 seconds after the start, <strong>Refresh license status</strong> shows the result.</li><li>If the error stays, or the stop date is close, contact <a href="/docs/support">support</a> with the error text and the date. Do not send the licence token.</li></ol><p>The backend log shows the same events (<code>Seat usage report failed.</code>, <code>Seat report rejected</code>). More on the card: <a href="/docs/admin#check-renewal-health">Check renewal health</a>.</p><h3 id="seats" tabindex="-1">Seats <a class="header-anchor" href="#seats" aria-label="Permalink to &quot;Seats&quot;">​</a></h3><p>A seat is a user who has signed in at least once and whose seat an administrator has not revoked. With a licence, every user gets a seat on sign-in. <strong>Settings → Users &amp; seats</strong> shows the seats in use against the seats included; untick a user to revoke the seat. Revoke the seats of people who no longer use the instance, since the reported count is the number of seats in use.</p><h3 id="manual-invoicing" tabindex="-1">Manual invoicing <a class="header-anchor" href="#manual-invoicing" aria-label="Permalink to &quot;Manual invoicing&quot;">​</a></h3><p>If your organisation does not pay through the self-service checkout, the licence comes with your order form and you are invoiced separately.</p><div class="info custom-block"><p class="custom-block-title">Terms: per your order form</p><p>Invoicing interval, payment terms, seat count, how seat changes are invoiced, and the licence term are set by your order form. This page does not describe them.</p></div><p>With manual invoicing, <strong>Settings → Billing &amp; invoices</strong> may not apply to you: invoices come the way your order form says.</p><h2 id="_4-before-the-team-starts" tabindex="-1">4. Before the team starts <a class="header-anchor" href="#_4-before-the-team-starts" aria-label="Permalink to &quot;4. Before the team starts&quot;">​</a></h2><ul><li><strong>Back up</strong> the database, the Secret <code>agenthub-data-protection</code>, your values and the object storage bucket from the first day; the stored secrets cannot be decrypted without that Secret. Rehearse a restore in a separate environment. See <a href="/docs/upgrading#before-every-upgrade">Before every upgrade</a>.</li><li><strong>Leave experimental features off.</strong> <code>agent.workspaceVolume.persistent</code> (the provider switch) stays <code>false</code>, the chart default.</li><li><strong>Agree how you will upgrade.</strong> Read <a href="/docs/upgrading">Upgrading</a> and plan the first upgrade before you need it.</li><li><strong>Enterprise: plan the onboarding sessions</strong> within the first 30 days; see <a href="/docs/support#onboarding">Onboarding</a>.</li><li><strong>Know where to get help.</strong> See <a href="/docs/support">Support</a>.</li></ul>`,48)])])}const g=t(i,[["render",r]]);export{u as __pageData,g as default};
